import java.io.*;
import java.util.*;

public class Main {
    static final InputStream in = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int gc() throws IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = gc();
        while (c != '-' && (c < '0' || c > '9')) {
            if (c == -1) return 0;
            c = gc();
        }
        boolean neg = false;
        if (c == '-') { neg = true; c = gc(); }
        long v = 0;
        while (c >= '0' && c <= '9') { v = v * 10 + (c - '0'); c = gc(); }
        return neg ? -v : v;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        int[] pos = new int[n];
        int sz = 0;
        for (int i = 0; i < n; i++) {
            int v = (int) nextLong();
            if (v > 0) pos[sz++] = v;
        }
        // The answer is the number of distinct positive stock values.
        Arrays.sort(pos, 0, sz);
        int distinct = 0;
        for (int i = 0; i < sz; i++) if (i == 0 || pos[i] != pos[i - 1]) distinct++;
        System.out.println(distinct);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"slices"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<16)

func readInt() int64 {
	c, err := rd.ReadByte()
	for err == nil && c != '-' && (c < '0' || c > '9') {
		c, err = rd.ReadByte()
	}
	if err != nil {
		return 0
	}
	neg := false
	if c == '-' {
		neg = true
		c, err = rd.ReadByte()
	}
	var v int64
	for err == nil && c >= '0' && c <= '9' {
		v = v*10 + int64(c-'0')
		c, err = rd.ReadByte()
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	n := int(readInt())
	pos := make([]int32, 0, n)
	for i := 0; i < n; i++ {
		if v := int32(readInt()); v > 0 {
			pos = append(pos, v)
		}
	}
	// The answer is the number of distinct positive stock values.
	slices.Sort(pos)
	fmt.Println(len(slices.Compact(pos)))
}
